```python
class Memoize:
    def __init__(self, func):
        self.func = func
        self.cache = {}
        self.call_count = 0
        self.hit_count = 0

    def __call__(self, *args):
        self.call_count += 1
        if args in self.cache:
            self.hit_count += 1
            return self.cache[args]
        ergebnis = self.func(*args)
        self.cache[args] = ergebnis
        return ergebnis

    def stats(self):
        return {
            'calls': self.call_count,
            'hits': self.hit_count,
            'cache_size': len(self.cache),
            'hit_rate': self.hit_count / max(self.call_count, 1)
        }

@Memoize
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

print(fibonacci(30))
print(fibonacci.stats())
```

