```python
import hashlib
import secrets

def hash_passwort(passwort: str) -> str:
    # Zufälliges Salt generieren
    salt = secrets.token_hex(16)
    # Passwort + Salt hashen
    hash_wert = hashlib.sha256(
        (passwort + salt).encode()
    ).hexdigest()
    return f'{salt}${hash_wert}'

def verifiziere_passwort(passwort: str, gespeichert: str) -> bool:
    salt, hash_wert = gespeichert.split('$')
    neu_hash = hashlib.sha256(
        (passwort + salt).encode()
    ).hexdigest()
    return secrets.compare_digest(neu_hash, hash_wert)

# Oder besser: bcrypt (pip install bcrypt)
import bcrypt

def hash_mit_bcrypt(passwort: str) -> str:
    salt = bcrypt.gensalt(rounds=12)
    return bcrypt.hashpw(passwort.encode(), salt).decode()

def verify_mit_bcrypt(passwort: str, hash_wert: str) -> bool:
    return bcrypt.checkpw(passwort.encode(), hash_wert.encode())
