class SingletonMeta(type):
    _instances = {}

    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]

class PluginMeta(type):
    registry = {}

    def __new__(mcs, name, bases, namespace):
        cls = super().__new__(mcs, name, bases, namespace)
        if name != 'BasePlugin':  # Abstrakte Basisklasse ausschließen
            mcs.registry[name.lower()] = cls
        return cls

class BasePlugin(metaclass=PluginMeta):
    @abstractmethod
    def execute(self):
        pass

class TextPlugin(BasePlugin):
    def execute(self):
        return 'Text verarbeitet'

class BildPlugin(BasePlugin):
    def execute(self):
        return 'Bild verarbeitet'

# Plugin-Registry nutzen
for name, plugin_class in PluginMeta.registry.items():
    print(f'{name}: {plugin_class().execute()}')
