from fastapi import FastAPI, Depends, HTTPException, status
from fastapi.security import HTTPBearer, HTTPAuthorizationCredentials
from jose import JWTError, jwt
from datetime import datetime, timedelta
from pydantic import BaseModel

app = FastAPI()
SECRET_KEY = 'dein-geheimer-schlüssel'
ALGORITHM = 'HS256'
ACCESS_TOKEN_EXPIRE_MINUTES = 30

class TokenData(BaseModel):
    username: str | None = None

def erstelle_token(daten: dict):
    zu_kodieren = daten.copy()
    ablauf = datetime.utcnow() + timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)
    zu_kodieren.update({'exp': ablauf})
    return jwt.encode(zu_kodieren, SECRET_KEY, algorithm=ALGORITHM)

async def aktueller_nutzer(token: HTTPAuthorizationCredentials = Depends(HTTPBearer())):
    try:
        payload = jwt.decode(token.credentials, SECRET_KEY, algorithms=[ALGORITHM])
        username = payload.get('sub')
        if username is None:
            raise HTTPException(status_code=401)
        return TokenData(username=username)
    except JWTError:
        raise HTTPException(status_code=401)

@app.get('/profil')
async def profil(nutzer: TokenData = Depends(aktueller_nutzer)):
    return {'message': f'Willkommen, {nutzer.username}!'}
