from __future__ import annotations
from dataclasses import dataclass, field
from typing import List, Optional
from datetime import datetime
from uuid import uuid4, UUID
from enum import Enum, auto

class BestellStatus(Enum):
    OFFEN = auto()
    BEZAHLT = auto()
    VERSendet = auto()
    STORNIERT = auto()

@dataclass
class BestellPosition:
    produkt_id: UUID
    produkt_name: str
    menge: int
    einzelpreis: float

    @property
    def gesamtpreis(self) -> float:
        return self.menge * self.einzelpreis

@dataclass
class Bestellung:
    id: UUID = field(default_factory=uuid4)
    kunde_id: UUID = field(default_factory=uuid4)
    positionen: List[BestellPosition] = field(default_factory=list)
    status: BestellStatus = BestellStatus.OFFEN
    erstellt_am: datetime = field(default_factory=datetime.utcnow)
    _domain_events: List = field(default_factory=list, repr=False)

    def position_hinzufuegen(self, position: BestellPosition):
        if self.status != BestellStatus.OFFEN:
            raise ValueError('Nur offene Bestellungen können bearbeitet werden')
        self.positionen.append(position)

    @property
    def gesamtsumme(self) -> float:
        return sum(p.gesamtpreis for p in self.positionen)

    def bezahlen(self):
        if self.status != BestellStatus.OFFEN:
            raise ValueError('Bestellung kann nicht bezahlt werden')
        if not self.positionen:
            raise ValueError('Leere Bestellung')
        self.status = BestellStatus.BEZAHLT
        self._domain_events.append(BestellungBezahltEvent(self.id))

    def pop_events(self) -> List:
        events = self._domain_events[:]
        self._domain_events.clear()
        return events

@dataclass
class BestellungBezahltEvent:
    bestell_id: UUID
    zeitstempel: datetime = field(default_factory=datetime.utcnow)
