```python
def binaere_suche(arr, ziel):
    links, rechts = 0, len(arr) - 1

    while links <= rechts:
        mitte = (links + rechts) // 2
        if arr[mitte] == ziel:
            return mitte
        elif arr[mitte] < ziel:
            links = mitte + 1
        else:
            rechts = mitte - 1

    return -1  # Nicht gefunden

# Rekursive Variante
def binaere_suche_rek(arr, ziel, links=0, rechts=None):
    if rechts is None:
        rechts = len(arr) - 1

    if links > rechts:
        return -1

    mitte = (links + rechts) // 2
    if arr[mitte] == ziel:
        return mitte
    elif arr[mitte] < ziel:
        return binaere_suche_rek(arr, ziel, mitte + 1, rechts)
    else:
        return binaere_suche_rek(arr, ziel, links, mitte - 1)

# Verwendung
sortiert = [1, 3, 5, 7, 9, 11, 13, 15]
print(binaere_suche(sortiert, 7))   # 3
print(binaere_suche(sortiert, 10))  # -1
```

