```python
class DIContainer:
    def __init__(self):
        self._registrations = {}
        self._singletons = {}

    def register(self, interface, implementation, lifetime='transient'):
        self._registrations[interface] = {
            'impl': implementation,
            'lifetime': lifetime
        }

    def resolve(self, interface):
        reg = self._registrations.get(interface)
        if not reg:
            raise KeyError(f'{interface} nicht registriert')

        if reg['lifetime'] == 'singleton':
            if interface not in self._singletons:
                self._singletons[interface] = reg['impl']()
            return self._singletons[interface]

        return reg['impl']()

# Verwendung
class IDatabase:
    pass

class PostgresDB(IDatabase):
    def query(self, sql):
        return f'Postgres: {sql}'

container = DIContainer()
container.register(IDatabase, PostgresDB, 'singleton')
db = container.resolve(IDatabase)
```

