def get_produkte():
    return jsonify(produkte)

@app.route('/api/produkte/<int:id>', methods=['GET'])
def get_produkt(id):
    produkt = next((p for p in produkte if p['id'] == id), None)
    if produkt is None:
        return jsonify({'fehler': 'Nicht gefunden'}), 404
    return jsonify(produkt)

@app.route('/api/produkte', methods=['POST'])
def create_produkt():
    daten = request.get_json()
    neues_produkt = {
        'id': len(produkte) + 1,
        'name': daten['name'],
        'preis': daten['preis']
    }
    produkte.append(neues_produkt)
    return jsonify(neues_produkt), 201

if __name__ == '__main__':
    app.run(debug=True, port=5000)
